import java.io.*;
import java.util.*;

public class Main {
    static final InputStream IN = System.in;
    static final byte[] BUF = new byte[1 << 16];
    static int len, ptr;

    static int readByte() throws IOException {
        if (ptr == len) {
            len = IN.read(BUF, 0, BUF.length);
            ptr = 0;
            if (len <= 0) {
                len = 0;
                return -1;
            }
        }
        return BUF[ptr++];
    }

    static long nextLong() throws IOException {
        int c = readByte();
        while (c == ' ' || c == '\n' || c == '\r' || c == '\t') c = readByte();
        boolean neg = c == '-';
        if (neg) c = readByte();
        long v = 0;
        while (c >= '0' && c <= '9') {
            v = v * 10 + (c - '0');
            c = readByte();
        }
        return neg ? -v : v;
    }

    static int nextInt() throws IOException {
        return (int) nextLong();
    }

    static String next() throws IOException {
        int c = readByte();
        while (c == ' ' || c == '\n' || c == '\r' || c == '\t') c = readByte();
        StringBuilder sb = new StringBuilder();
        while (c > ' ') {
            sb.append((char) c);
            c = readByte();
        }
        return sb.toString();
    }

    public static void main(String[] args) throws IOException {
        int n = nextInt();
        long[][] players = new long[n][];
        for (int i = 0; i < n; i++) {
            long[] p = {nextLong(), nextLong(), nextLong()};
            Arrays.sort(p);
            players[i] = p;
        }
        long[] col0 = extrema(players, 0), col1 = extrema(players, 1);
        // X beats Y iff middle(X) > min(Y) and max(X) > middle(Y).
        int answer = 0;
        for (int i = 0; i < n; i++) {
            long opponentMin = i == col0[2] ? col0[1] : col0[0];
            long opponentMiddle = i == col1[2] ? col1[1] : col1[0];
            if (players[i][1] > opponentMin && players[i][2] > opponentMiddle) answer++;
        }
        System.out.println(answer);
    }

    // {largest, second largest (equal values kept), owner of the largest} of a column.
    static long[] extrema(long[][] players, int column) {
        long best = -1, second = -1, owner = -1;
        for (int i = 0; i < players.length; i++) {
            long v = players[i][column];
            if (v > best) {
                second = best;
                best = v;
                owner = i;
            } else if (v > second) {
                second = v;
            }
        }
        return new long[] {best, second, owner};
    }
}

