import (
	"fmt"
	"io"
	"os"
	"sort"
)

var data []byte
var pos int

// token returns the next whitespace-separated token of stdin.
func token() []byte {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
	start := pos
	for pos < len(data) && data[pos] > ' ' {
		pos++
	}
	return data[start:pos]
}

func nextInt() int {
	b := token()
	neg := len(b) > 0 && b[0] == '-'
	if neg {
		b = b[1:]
	}
	v := 0
	for _, c := range b {
		v = v*10 + int(c-'0')
	}
	if neg {
		return -v
	}
	return v
}

// extrema returns the largest and second largest (equal values kept) of a column, and the owner of the largest.
func extrema(players [][3]int, column int) (best, second, owner int) {
	best, second, owner = -1, -1, -1
	for i, p := range players {
		v := p[column]
		if v > best {
			second, best, owner = best, v, i
		} else if v > second {
			second = v
		}
	}
	return
}

func main() {
	data, _ = io.ReadAll(os.Stdin)
	n := nextInt()
	players := make([][3]int, n)
	for i := range players {
