		sort.Ints(p)
		players[i] = [3]int{p[0], p[1], p[2]}
	}
	a, a2, ai := extrema(players, 0)
	b, b2, bi := extrema(players, 1)
	// X beats Y iff middle(X) > min(Y) and max(X) > middle(Y).
	answer := 0
